// Format the context from vector search results
const items = $input.all();

if (!items || items.length === 0) {
  return [{
    json: {
      context: "No relevant documentation found.",
      sources: []
    }
  }];
}

// Get the embedding from the first item
const embedding = items[0].json.embedding;

// Get search results (if any)
const searchResults = items.filter(item => item.json.content);

// Format context
const context = searchResults
  .slice(0, 5) // Top 5 results
  .map((item, idx) => {
    const metadata = item.json.metadata || {};
    return `[${idx + 1}] Source: ${metadata.source || 'Unknown'}\n${item.json.content}`;
  })
  .join('\n\n---\n\n');

// Format sources
const sources = searchResults
  .slice(0, 5)
  .map(item => {
    const metadata = item.json.metadata || {};
    return {
      title: metadata.source || 'Documentation',
      similarity: item.json.similarity
    };
  });

return [{
  json: {
    context: context || "No relevant documentation found.",
    sources: sources,
    embedding: embedding,
    userMessage: $('Webhook').first().json.body.message
  }
}];

// Format the final response
const chatResponse = $input.first().json.message?.content || "I'm having trouble generating a response.";
const sources = $('Format Context').first().json.sources || [];

return [{
  json: {
    answer: chatResponse,
    sources: sources,
    success: true
  }
}];
